def standard():
    x = Symbol('x')
    h = expand((-1)*x**0+(1)*x**1+(1)*x**2+(-1)*x**3)
    pts = [Integer(-1)] + sorted(set(r for r in solve(h, x) if r.is_real and -1 < r < 1)) + [Integer(1)]
    tot = 0
    for p_, q_ in zip(pts, pts[1:]):
        tot += Abs(integrate(h, (x, p_, q_)))
    tot = tot*Rational(12, 1)
    return int(tot)

def unique():
    return [standard()]
